import sys
import bisect

def main():
    import sys
    import bisect

    def read_ints():
        return list(map(int, sys.stdin.readline().split()))

    n, m = read_ints()
    playlist = []
    total_duration = 0

    for _ in range(n):
        c_i, t_i = read_ints()
        playlist.append((total_duration, total_duration + c_i * t_i))
        total_duration += c_i * t_i

    moments = read_ints()

    results = []
    for moment in moments:
        # Find the rightmost index where the moment is less than or equal to the end time of the song
        idx = bisect.bisect_right(playlist, moment, key=lambda x: x[1])
        if idx == 0:
            results.append(1)
        else:
            results.append(idx)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
